// Generated by the e2e-perfromance-test-suite-k6 skill.
// The full-transaction scenario the "Concurrent Users" and "TAT" NFRs are
// measured against: browse products -> view a product's detail -> guest
// checkout -> view the placed order. SmartBuy has no auth (guest checkout
// only, per CLAUDE.md), so there's no register/login step. Mirrors
// src/pages/Checkout.jsx's POST /api/orders payload shape -- the server
// re-prices everything from the DB (server/routes/orders.js), so
// client-submitted prices are irrelevant here.
import http from 'k6/http';
import { check, group, sleep } from 'k6';
import { Trend } from 'k6/metrics';
import { apiUrl, jsonHeaders } from '../lib/http-client.js';

export const tatTrend = new Trend('order_lifecycle_tat_ms', true);

function uniqueShipping() {
  const suffix = `${__VU}-${__ITER}-${Date.now()}`;
  return {
    fullName: `K6 Load Tester ${suffix}`,
    address: `${100 + (__VU % 900)} Load Test Ave`,
    city: 'Loadtestville',
    zip: String(10000 + Math.floor(Math.random() * 89999)),
  };
}

export function orderLifecycle() {
  const startedAt = Date.now();

  group('order_lifecycle', () => {
    let products;
    group('browse_products', () => {
      const res = http.get(apiUrl('/api/products'));
      const ok = check(res, {
        'list products: 200': (r) => r.status === 200,
        'list products: non-empty': (r) => r.status === 200 && r.json().length > 0,
      });
      if (ok) products = res.json();
    });

    if (!products) return;

    const product = products[Math.floor(Math.random() * products.length)];

    group('view_product', () => {
      const res = http.get(apiUrl(`/api/products/${product.id}`));
      check(res, { 'product detail: 200': (r) => r.status === 200 });
    });

    // 1-2 distinct line items, qty 1-3 each -- enough variety that many
    // concurrent VUs aren't all placing an identical cart every iteration.
    const items = [{ productId: product.id, qty: 1 + Math.floor(Math.random() * 3) }];
    if (Math.random() < 0.4) {
      const other = products[Math.floor(Math.random() * products.length)];
      if (other.id !== product.id) {
        items.push({ productId: other.id, qty: 1 + Math.floor(Math.random() * 3) });
      }
    }

    let orderId;
    group('checkout', () => {
      const res = http.post(
        apiUrl('/api/orders'),
        JSON.stringify({ items, shipping: uniqueShipping() }),
        jsonHeaders(),
      );
      const ok = check(res, { 'checkout: 201': (r) => r.status === 201 });
      if (ok) orderId = res.json('id');
    });

    if (orderId) {
      group('view_order', () => {
        const res = http.get(apiUrl(`/api/orders/${orderId}`));
        check(res, { 'view order: 200': (r) => r.status === 200 });
      });
    }
  });

  tatTrend.add(Date.now() - startedAt);
  sleep(1); // think-time between a simulated user's sessions
}

// Allows `k6 run tests/order-lifecycle.js` standalone for a quick,
// unparameterized check of just this flow (fixed light load -- the full NFR
// profile always runs through tests/load-test.js instead).
export const options = {
  scenarios: {
    standalone: { executor: 'shared-iterations', vus: 5, iterations: 20, exec: 'orderLifecycle' },
  },
  thresholds: {
    http_req_failed: ['rate<0.05'],
  },
};
